Q: MPU6050 Gyro causing esp32 to crash silently when running IMU_ZERO calibration A: <p><strong>EDIT:</strong><br />
The board is an MPU6500. After hassling with abstractions of different libraries, (<a href="https://github.com/Git-Hub-Dangel/invensense-imu" rel="nofollow noreferrer">InvenSense IMU</a>, Electronic Cat's MPU6050) I got tired and settled to writing my own driver links with <a href="https://github.com/libdriver/mpu6500" rel="nofollow noreferrer">LibDriver's MPU6500</a>. It is much more work to set up and get running, but well worth the effort as it offers the whole hardware feature-set of the MPU6500.</p>
<p>Docs: <a href="https://www.libdriver.com/docs/mpu6500" rel="nofollow noreferrer">https://www.libdriver.com/docs/mpu6500</a></p>
<p><strong>ORIGINAL ANSWER:</strong></p>
<p>Solved the issue. Turns out the gyro is an <code>MPU6500</code> in disguise.</p>
<p>I bypassed the library and pinged the I2C bus directly. Reading the <code>WHO_AM_I</code> register (0x75) returned <code>0x70</code>. A genuine MPU6050 should give <code>0x68</code>.</p>
<p>The <code>0x70</code> ID seems to belong to the MPU6500. I think producers are taking newer MPU6500 dies and laser etching them as MPU6050s for whatever reason. Standard libraries (like I2Cdev) fail because their strict device ID checks expect the old <code>0x68</code> signature.</p>
<p>Fortunately the MPU6500 is register-compatible with the 6050. I’ve modified the standard <code>IMU_Zero</code> calibration sketch by Electronic Cats to bypass the strict ID check and explicitly bind the ESP32-C6 I2C pins (<code>Wire.begin(SCL, SDA)</code>).</p>
<p>If your &quot;MPU6050&quot; refuses to connect, you likely have a disguised 6500. Took me a while to resolve. If you're stuck at this sketch silently failing, try this slightly modified snippet instead of the official IMU_ZERO.</p>
<pre class="lang-cpp prettyprint-override"><code>/*
  IMU Zero (Modified for ESP32-C6 and MPU6500 Compatibility)

  Calibrates the MPU6050/MPU6500 to compensate for measurement deviations or errors that may
  occur due to factors such as gyroscope and accelerometer offset.
*/

#include &lt;I2Cdev.h&gt;
#include &lt;MPU6050.h&gt;
#include &lt;Wire.h&gt;

/* Create the class for MPU6050. Default I2C address is 0x68 */
MPU6050 mpu;
// MPU6050 mpu(0x69); // &lt;-- use for AD0 high

const int usDelay = 3150; // Delay in ms to hold the sampling at 200Hz
const int NFast = 1000; // Number of quick readings for averaging, the higher the better
const int NSlow = 10000; // Number of slow readings for averaging, the higher the better
const int LinesBetweenHeaders = 5;

const int iAx = 0;
const int iAy = 1;
const int iAz = 2;
const int iGx = 3;
const int iGy = 4;
const int iGz = 5;

int LowValue[6];
int HighValue[6];
int Smoothed[6];
int LowOffset[6];
int HighOffset[6];
int Target[6];
int LinesOut;
int N;
int i;

void SetAveraging(int NewN);
void PullBracketsOut();
void PullBracketsIn();
void ForceHeader();
void GetSmoothed();
void SetOffsets(int TheOffsets[6]);
void ShowProgress();
void Initialize();

void setup() {
  Initialize(); //Initializate and calibrate the sensor
  for (i = iAx; i &lt;= iGz; i++) { 
    Target[i] = 0; // Fix for ZAccel 
    HighOffset[i] = 0;
    LowOffset[i] = 0;
  } 
  Target[iAz] = 16384; // Set the taget for Z axes
  SetAveraging(NFast); // Fast averaging
  PullBracketsOut();
  PullBracketsIn();
  Serial.println(&quot;-------------- DONE --------------&quot;);
}

void loop() {
  //Write your code here
} 

/*Initializate function*/
void Initialize() {
  Serial.begin(9600);

  // Wait for serial monitor to connect
  delay(2000);

  Serial.println(&quot;Initializing I2C...&quot;);

  #if I2CDEV_IMPLEMENTATION == I2CDEV_ARDUINO_WIRE
    Wire.begin(SCL, SDA);
  #elif I2CDEV_IMPLEMENTATION == I2CDEV_BUILTIN_FASTWIRE
    Fastwire::setup(400, true);
  #endif

  // Init the module
  Serial.println(&quot;Initializing MPU...&quot;);
  mpu.initialize();
  Serial.println(&quot;MPU initialized&quot;);

  // Check module connection using Device ID bypass for MPU6500
  Serial.println(&quot;Testing device connections...&quot;);
  uint8_t devID = mpu.getDeviceID();

  // 0x34 = MPU6050, 0x38 = MPU6500
  if(devID != 0x34 &amp;&amp; devID != 0x38) {
    Serial.print(&quot;MPU connection failed. Unknown Device ID: 0x&quot;);
    Serial.println(devID, HEX);
    while(true);
  } else {
    Serial.print(&quot;MPU connection successful. Found Device ID: 0x&quot;);
    Serial.println(devID, HEX);
    if (devID == 0x38) {
      Serial.println(&quot;Note: Operating with MPU6500 compatibility.&quot;);
    }
  }

  Serial.println(&quot;\nPID tuning Each Dot = 100 readings&quot;);
  /*
  PID tuning (actually PI) works like this: changing the offset in the MPU6050 gives instant results, 
  allowing us to use the Proportional and Integral parts of the PID to find the ideal offsets. 
  The Integral uses the error from the set point (which is zero) and adds a fraction of this error to 
  the integral value. Each reading reduces the error towards the desired offset. The greater 
  the error, the more we adjust the integral value. 

  The Proportional part helps by filtering out noise from the integral calculation. The Derivative part is 
  not used due to noise and the sensor being stationary. With the noise removed, the integral value stabilizes 
  after about 600 readings. At the end of each set of 100 readings, the integral value is used for the actual 
  offsets, and the last proportional reading is ignored because it reacts to any noise.
  */
  Serial.println(&quot;\nXAccel\t\tYAccel\t\tZAccel\t\tXGyro\t\tYGyro\t\tZGyro&quot;);
  mpu.CalibrateAccel(6);
  mpu.CalibrateGyro(6);
  Serial.println(&quot;\n600 Readings&quot;);
  mpu.PrintActiveOffsets();
  mpu.CalibrateAccel(1);
  mpu.CalibrateGyro(1);
  Serial.println(&quot;700 Total Readings&quot;);
  mpu.PrintActiveOffsets();
  mpu.CalibrateAccel(1);
  mpu.CalibrateGyro(1);
  Serial.println(&quot;800 Total Readings&quot;);
  mpu.PrintActiveOffsets();
  mpu.CalibrateAccel(1);
  mpu.CalibrateGyro(1);
  Serial.println(&quot;900 Total Readings&quot;);
  mpu.PrintActiveOffsets();
  mpu.CalibrateAccel(1);
  mpu.CalibrateGyro(1);
  Serial.println(&quot;1000 Total Readings&quot;);
  mpu.PrintActiveOffsets();
  Serial.println(&quot;\nAny of the above offsets will work nicely \n\nProving the PID with other method:&quot;);
}

void SetAveraging(int NewN) {
  N = NewN;
  Serial.print(&quot;\nAveraging &quot;);
  Serial.print(N);
  Serial.println(&quot; readings each time&quot;);
}

void PullBracketsOut() {
  boolean Done = false;
  int NextLowOffset[6];
  int NextHighOffset[6];

  Serial.println(&quot;Expanding:&quot;);
  ForceHeader();

  while (!Done) {
    Done = true;
    SetOffsets(LowOffset); //Set low offsets
    GetSmoothed();
    for (i = 0; i &lt;= 5; i++) { // Get low values
      LowValue[i] = Smoothed[i];
      if (LowValue[i] &gt;= Target[i]) {
        Done = false;
        NextLowOffset[i] = LowOffset[i] - 1000;
      } 
      else {
        NextLowOffset[i] = LowOffset[i];
      }
    }
    SetOffsets(HighOffset);
    GetSmoothed();
    for (i = 0; i &lt;= 5; i++) { // Get high values
      HighValue[i] = Smoothed[i];
      if (HighValue[i] &lt;= Target[i]) {
        Done = false;
        NextHighOffset[i] = HighOffset[i] + 1000;
      } 
      else {
        NextHighOffset[i] = HighOffset[i];
      }
    } 
    ShowProgress();
    for (int i = 0; i &lt;= 5; i++) {
      LowOffset[i] = NextLowOffset[i]; 
      HighOffset[i] = NextHighOffset[i];
    }
  }
}

void PullBracketsIn() {
  boolean AllBracketsNarrow;
  boolean StillWorking;
  int NewOffset[6];

  Serial.println(&quot;\nClosing in:&quot;);
  AllBracketsNarrow = false;
  ForceHeader();
  StillWorking = true;
  while (StillWorking) {
    StillWorking = false;
    if (AllBracketsNarrow &amp;&amp; (N == NFast)) {
      SetAveraging(NSlow);
    } 
    else {
      AllBracketsNarrow = true;
    }
    for (int i = 0; i &lt;= 5; i++) {
      if (HighOffset[i] &lt;= (LowOffset[i] + 1)) {
        NewOffset[i] = LowOffset[i];
      } 
      else { // Binary search
        StillWorking = true;
        NewOffset[i] = (LowOffset[i] + HighOffset[i]) / 2;
        if (HighOffset[i] &gt; (LowOffset[i] + 10)) {
          AllBracketsNarrow = false;
        }
      } 
    }
    SetOffsets(NewOffset);
    GetSmoothed();
    for (i = 0; i &lt;= 5; i++) { // Closing in
      if (Smoothed[i] &gt; Target[i]) { // Use lower half
        HighOffset[i] = NewOffset[i];
        HighValue[i] = Smoothed[i];
      } 
      else { // Use upper half
        LowOffset[i] = NewOffset[i];
        LowValue[i] = Smoothed[i];
      } 
    }
    ShowProgress();
  } 
} 

void ForceHeader() {
  LinesOut = 99;
}

/*Function to smooth the read values*/
void GetSmoothed() {
  int16_t RawValue[6];
  long Sums[6];
  for (i = 0; i &lt;= 5; i++) {
    Sums[i] = 0;
  }

/* Get Sums*/
  for (i = 1; i &lt;= N; i++) { 
    mpu.getMotion6( &amp; RawValue[iAx], &amp; RawValue[iAy], &amp; RawValue[iAz], &amp; RawValue[iGx], &amp; RawValue[iGy], &amp; RawValue[iGz]);
    delayMicroseconds(usDelay);
    for (int j = 0; j &lt;= 5; j++){
      Sums[j] = Sums[j] + RawValue[j];
    }
  } 
  for (i = 0; i &lt;= 5; i++) {
    Smoothed[i] = (Sums[i] + N / 2) / N;
  }
} 

/*Function for configure the oba=tained offsets*/
void SetOffsets(int TheOffsets[6]) {
  mpu.setXAccelOffset(TheOffsets[iAx]);
  mpu.setYAccelOffset(TheOffsets[iAy]);
  mpu.setZAccelOffset(TheOffsets[iAz]);
  mpu.setXGyroOffset(TheOffsets[iGx]);
  mpu.setYGyroOffset(TheOffsets[iGy]);
  mpu.setZGyroOffset(TheOffsets[iGz]);
}

/*Print the progress of the reading averages, add formatting for better visualization*/
void ShowProgress() {
 /*Header*/
  if (LinesOut &gt;= LinesBetweenHeaders) { 
    Serial.println(&quot;\t\tXAccel\t\t\tYAccel\t\t\t\tZAccel\t\t\tXGyro\t\t\tYGyro\t\t\tZGyro&quot;);
    LinesOut = 0;
  } 
  Serial.print(' ');
  for (i = 0; i &lt;= 5; i++) {
    Serial.print('[');
    Serial.print(LowOffset[i]),
    Serial.print(',');
    Serial.print(HighOffset[i]);
    Serial.print(&quot;] --&gt; [&quot;);
    Serial.print(LowValue[i]);
    Serial.print(',');
    Serial.print(HighValue[i]);
    if (i == 5) {
      Serial.println(&quot;]&quot;);
    } 
    else {
      Serial.print(&quot;]\t&quot;);
    }
  }
  LinesOut++;
}
</code></pre>
